/// The compiled-in protection list.
///
/// Generated by `Scripts/generate-protection.py` from the Rust constants in
/// `RustCore/crates/sift-rules/src/lib.rs`. Do not edit by hand: one source
/// is what stops this engine and the Rust scanner core from protecting
/// different sets of paths.
public enum ProtectedPaths {
    /// Why a `~/Library` child is protected.
    public enum LibraryKind: Sendable, Equatable {
        /// Holds user data rather than application state.
        case userContent
        /// Holds credentials, accounts or private messages.
        case secrets
    }

    /// Paths that are never scanned or cleaned, as children of the home folder.
    public static let homeChildren: Set<String> = [
        "Documents",
        "Desktop",
        "Movies",
        "Music",
        "Pictures",
        "Projects",
        "Developer",
        "Public",
    ]

    /// Absolute prefixes that are never scanned or cleaned. Only `/Volumes`
    /// may be lifted, and only for a subtree the user granted.
    public static let prefixes: [String] = [
        "/System",
        "/bin",
        "/sbin",
        "/usr",
        "/etc",
        "/private/etc",
        "/private/var/db",
        "/private/var/vm",
        "/Library/Apple",
        "/Library/Extensions",
        "/Library/LaunchDaemons",
        "/Library/LaunchAgents",
        "/Library/StagedExtensions",
        "/Volumes",
    ]

    /// `~/Library` children that hold secrets or user data, with the reason.
    public static let libraryChildren: [(path: String, kind: LibraryKind)] = [
        ("Library/Keychains", .secrets),
        ("Library/Mobile Documents", .userContent),
        ("Library/Accounts", .secrets),
        ("Library/Messages", .secrets),
        ("Library/Mail", .secrets),
        ("Library/Safari", .secrets),
        ("Library/Cookies", .secrets),
    ]

    /// Suffix of a photo library package, protected as one unit.
    public static let photosLibrarySuffix = ".photoslibrary"
}
